import json
import itertools

def solve_puzzle():
    houses = [0, 1, 2, 3]  # indices for houses 1..4

    Names = ['Peter', 'Alice', 'Eric', 'Arnold']
    Mothers = ['Janelle', 'Holly', 'Aniya', 'Kailyn']
    Smoothies = ['watermelon', 'dragonfruit', 'desert', 'cherry']
    Heights = ['tall', 'average', 'short', 'very short']
    Educations = ['high school', 'associate', 'master', 'bachelor']

    solutions = []

    # Helper to get index of a value in an assignment list
    def idx(assign, value):
        return assign.index(value)

    # Enumerate mothers with Janelle fixed at house 3 (index 2)
    other_mothers = [m for m in Mothers if m != 'Janelle']  # ['Holly','Aniya','Kailyn']
    for perm_m in itertools.permutations(other_mothers):
        mother = [None]*4
        mother[2] = 'Janelle'
        # Assign the remaining mothers to houses 0,1,3
        m_positions = [0, 1, 3]
        for i, pos in enumerate(m_positions):
            mother[pos] = perm_m[i]

        # Heights with tall fixed at house 3 (index 2)
        other_heights = [h for h in Heights if h != 'tall']  # ['average','short','very short']
        for perm_h in itertools.permutations(other_heights):
            height = [None]*4
            height[2] = 'tall'
            h_positions = [0, 1, 3]
            for i, pos in enumerate(h_positions):
                height[pos] = perm_h[i]

            # Constraint 9: The person who is tall is the person whose mother's name is Janelle.
            if idx(height, 'tall') != idx(mother, 'Janelle'):
                continue  # Should always be true by construction, but keep for safety

            # Smoothies permutations (will enforce constraints 3, 8, 11)
            for smoothie in itertools.permutations(Smoothies):
                # Constraint 3: The Desert smoothie lover is not in the first house.
                if smoothie[0] == 'desert':
                    continue

                # Constraint 11: The Dragonfruit smoothie lover is directly left of the person who is short.
                try:
                    if idx(smoothie, 'dragonfruit') + 1 != idx(height, 'short'):
                        continue
                except ValueError:
                    continue  # if not found, but permutations guarantee presence

                # Constraint 8: The person who likes Cherry smoothies is the person whose mother's name is Aniya.
                if idx(smoothie, 'cherry') != idx(mother, 'Aniya'):
                    continue

                # Education permutations (constraints 2, 6, 7)
                for education in itertools.permutations(Educations):
                    # Constraint 6: The person with a high school diploma is not in the third house.
                    if education[2] == 'high school':
                        continue

                    # Constraint 2: The Desert smoothie lover is the person with a master's degree.
                    if education[idx(smoothie, 'desert')] != 'master':
                        continue
                    # Also ensure the reverse (master -> desert) since uniqueness in each category
                    if smoothie[idx(education, 'master')] != 'desert':
                        continue

                    # Constraint 7: The person whose mother's name is Kailyn is the person with an associate's degree.
                    if education[idx(mother, 'Kailyn')] != 'associate':
                        continue

                    # Constraint 4: The person who is very short is somewhere to the left of the person with a high school diploma.
                    if idx(height, 'very short') >= idx(education, 'high school'):
                        continue

                    # Names permutations with Alice at tall position (constraints 5, 10, 12)
                    other_names = [n for n in Names if n != 'Alice']
                    for perm_n in itertools.permutations(other_names):
                        name = [None]*4
                        # Constraint 12: The person who is tall is Alice.
                        name[idx(height, 'tall')] = 'Alice'
                        # Fill remaining houses in order 0,1,3 (or any order except the tall house)
                        n_positions = [i for i in houses if name[i] is None]
                        for i, pos in enumerate(n_positions):
                            name[pos] = perm_n[i]

                        # Constraint 5: Eric and the person who likes Cherry smoothies are next to each other.
                        if abs(idx(name, 'Eric') - idx(smoothie, 'cherry')) != 1:
                            continue

                        # Constraint 10: Arnold is somewhere to the right of the person who has an average height.
                        if idx(name, 'Arnold') <= idx(height, 'average'):
                            continue

                        # All constraints satisfied; record solution
                        solutions.append({
                            "Name": name[:],
                            "Mother": mother[:],
                            "Smoothie": list(smoothie),
                            "Height": height[:],
                            "Education": list(education),
                        })

    # Prepare output using the first solution found
    if not solutions:
        raise RuntimeError("No solution found.")

    sol = solutions[0]
    header = ["House", "Name", "Mother", "Smoothie", "Height", "Education"]
    rows = []
    for i in range(4):
        rows.append([
            str(i+1),
            sol["Name"][i],
            sol["Mother"][i],
            sol["Smoothie"][i],
            sol["Height"][i],
            sol["Education"][i]
        ])

    output = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }
    return output

if __name__ == "__main__":
    result = solve_puzzle()
    print(json.dumps(result, ensure_ascii=False))
